  'ui.contractor.helpAnswerUpdateProfile': 'انقر على اسمك في الزاوية العلوية اليمنى، واختر إعدادات الملف الشخصي، ثم عدّل أي قسم. لكل حقل زر تعديل خاص به مع حفظ وإلغاء. تُحفظ التغييرات في ملفك الحالي وتظهر فورًا في لوحة التحكم بالكامل.',
