  'site.calculators.propertyTds.previousBody': 'تقع هذه المعاملة ضمن الإطار الضريبي السابق (تاريخ الخصم {date}). تعتمد الحاسبة الحالية على Income-tax Act, 2025 للمعاملات اعتبارًا من 1 أبريل 2026 فصاعدًا، لذا لا يُحتسب أي مبلغ هنا. تحقّق من قواعد Section 194-IA السابقة لهذه المعاملة.',
