  'site.calculators.stampDuty.method': 'رسوم الدمغة = النسبة × قيمة العقار؛ رسوم التسجيل = النسبة × قيمة العقار؛ الرسوم الفعلية = الإجمالي ÷ قيمة العقار × 100. تُطبَّق الرسوم هنا على القيمة التي تدخلها، لكن الرسوم الفعلية تُقدَّر على أساس القيمة الإرشادية الحكومية (السوقية) أو قيمة الصفقة وفق ما تقتضيه القواعد المعمول بها، لذا فهذا تقدير وليس التقييم القانوني النهائي. تُقرَّب المبالغ إلى أقرب روبية للعرض.',
