  'site.calculators.trueCost.sourceTelangana': 'نسب ولاية تيلانغانا (Telangana): رسوم الدمغة على البيع 5.5% (G.O.Ms.No.59، إدارة الإيرادات (التسجيل)، 20-07-2021، سارية من 22-07-2021)؛ ورسوم التسجيل على عقود البيع 0.5%، أو 2% في نطاق غرام بانشايات (Gram Panchayat) (جدول الرسوم بموجب Section 78 من Registration Act، ساري من 02-09-2021). تحدد هذه الأوامر نسبة واحدة بغض النظر عن نوع المشتري أو الاستخدام السكني/التجاري. تُفرض الرسوم على القيمة السوقية (الإرشادية) أو السعر، أيهما أعلى؛ وتطبقها هذه الحاسبة على السعر الذي تدخله.',
